create temporary view  exp_traffic_info_${grass_region_without_quote}
as
select  group_id as exp_group_id
        ,layer_id
        ,experiment_id
from    abtest.shopee_experiment_admin_db__group_dimension_tab__reg_continuous_s0_live a
where   a.layer_id in (114215, 114572, 115980, 115981, 115983, 149987)
  and   scene_id = 527
  and   experiment_id in (135151, 135188, 136867, 136868, 136882, 178865)
;

