create temporary view  user_exp_${grass_region_without_quote}
as
select  user_id
        ,a.exp_group_id
        ,b.layer_id
--        ,case   when a.exp_group_id in (374110, 374204, 378760, 378769) then 'group2'
--                when a.exp_group_id in (374111, 374205, 378761, 378770) then 'group3'
--                when a.exp_group_id in (374112, 374206, 378762, 378771) then 'group4'
--                when a.exp_group_id in (374113, 374207, 378763, 378772) then 'group5'
--                when a.exp_group_id in (374114, 374208, 378764, 378773) then 'group6'
--                when a.exp_group_id in (374115, 374209, 378765, 378774) then 'group7'
--                when a.exp_group_id in (374116, 374210, 378766, 378775) then 'group8'
--                when a.exp_group_id = 378802 then 'group9_base'
--                when a.exp_group_id = 495845 then 'new_item_tc_base'
--                when a.exp_group_id = 495846 then 'new_item_tc_best'
--         end as group_name
from    user_exp_raw_${grass_region_without_quote} a
inner join exp_traffic_info_${grass_region_without_quote} b
on      a.exp_group_id = b.exp_group_id
union all
select  user_id
        ,-99999 as exp_group_id	--group2-group8混合实验组
        ,b.layer_id
from    user_exp_raw_${grass_region_without_quote} a
inner join exp_traffic_info_${grass_region_without_quote} b
on      a.exp_group_id = b.exp_group_id
where   case
        when a.exp_group_id in (374110, 374204, 378760, 378769) then 1
        when a.exp_group_id in (374111, 374205, 378761, 378770) then 1
        when a.exp_group_id in (374112, 374206, 378762, 378771) then 1
        when a.exp_group_id in (374113, 374207, 378763, 378772) then 1
        when a.exp_group_id in (374114, 374208, 378764, 378773) then 1
        when a.exp_group_id in (374115, 374209, 378765, 378774) then 1
        when a.exp_group_id in (374116, 374210, 378766, 378775) then 1
        else 0
    end = 1
;

