create temporary view  traffic_data_item_${grass_region_without_quote}
as
select  user_id
        ,item_id
        ,is_ads
        ,sum(imp_cnt) as imp_cnt
        ,sum(click_cnt) as click_cnt
        ,sum(order_cnt) as order_cnt
        ,sum(gmv) as gmv
        ,sum(gmv_local) as gmv_local
        ,sum(pc2_gmv) as pc2_gmv
from    (
    select  user_id
            ,item_id
            ,is_ads
            ,imp_cnt
            ,click_cnt
            ,order_cnt
            ,gmv
            ,gmv_local
            ,pc2_gmv
    from    srdi_mart.dwm_sr_data_warehouse_tc_ab_all_cards	-- is_item_card 为all 全部
    where   grass_region = ${grass_region}
      and   local_date = ${local_date}
)
group by 1, 2, 3
;

--sql_divide_splitter--
create temporary view  item_category_${grass_region_without_quote}
as
select  item_id
        ,level1_global_be_category_id
        ,level1_global_be_category
        ,level2_global_be_category_id
        ,level2_global_be_category
from    srdi_mart.dim_sr_data_warehouse_item
where   local_date = ${local_date}
  and   grass_region in (${grass_region})
  and   item_id > 0
;

--sql_divide_splitter--
create temporary view  basic_scene_data_${grass_region_without_quote}
as
select  T1.*
        ,T2.exp_group_id
        ,T2.layer_id
        ,T3.level1_global_be_category_id
        ,T3.level1_global_be_category
        ,T3.level2_global_be_category_id
        ,T3.level2_global_be_category
from    (
    select  T1.*
    from    (
        select  *
        from    traffic_data_item_${grass_region_without_quote}
    ) T1
    join    (	-- 仅90d内的item信息
        select  item_id
                ,max(item_create_datetime) as item_create_datetime
        from    srdi_mart.dim_sr_data_warehouse_item
        where   grass_region = ${grass_region}
          and   local_date = ${local_date}
          and   datediff(${local_date}, date(item_create_datetime)) <= 90
        group by 1
    ) T2
    on      T1.item_id = T2.item_id
) as T1
inner join user_exp_${grass_region_without_quote} as T2
on      T1.user_id = T2.user_id
left join item_category_${grass_region_without_quote} as T3
on      T1.item_id = T3.item_id
;

--sql_divide_splitter--
create temporary view  basic_shiping_channel_${grass_region_without_quote}
as
select  T1.*
        ,T2.exp_group_id
        ,T2.layer_id
from    (
    select  T1.*
    from    (
            select
            buyer_id as user_id
            ,item_id
                ,level1_global_be_category_id
                ,level1_global_be_category
                ,level2_global_be_category_id
                ,level2_global_be_category
                ,shipping_channel_id
            ,sum(order_fraction) AS order_cnt
            ,sum(gmv_usd) as gmv
            from
            mp_order.dwd_order_item_all_ent_df__reg_s0_live
            WHERE
            tz_type = 'local'
            AND grass_region IN (${grass_region})
            AND ( grass_date >=(${local_date}) OR grass_date = date'9999-01-01' )
            AND date(create_datetime) = ${local_date}
            AND (is_bi_excluded IS NULL OR is_bi_excluded = 0)
            group by 1,2,3,4,5,6, 7
    ) T1
    join    (	-- 仅90d内的item信息
        select  item_id
                ,max(item_create_datetime) as item_create_datetime
        from    srdi_mart.dim_sr_data_warehouse_item
        where   grass_region = ${grass_region}
          and   local_date = ${local_date}
          and   datediff(${local_date}, date(item_create_datetime)) <= 90
        group by 1
    ) T2
    on      T1.item_id = T2.item_id
) as T1
inner join user_exp_${grass_region_without_quote} as T2
on      T1.user_id = T2.user_id
;

--sql_divide_splitter--
INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_tc_ni_category_channel_exp_1d
partition (grass_region = ${grass_region},local_date = ${local_date})
SELECT
    layer_id
    ,exp_group_id
    ,level1_global_be_category_id
    ,level1_global_be_category
    ,level2_global_be_category_id
    ,level2_global_be_category

    ,'__ALL__' as shipping_channel_id
    ,COUNT(DISTINCT item_id) AS exposed_item_cnt
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
FROM
    basic_scene_data_${grass_region_without_quote}
    group by 1,2,3,4,5,6

union all

select
  layer_id
    ,exp_group_id
    ,level1_global_be_category_id
    ,level1_global_be_category
    ,level2_global_be_category_id
    ,level2_global_be_category
    ,shipping_channel_id
    ,0  AS exposed_item_cnt
    ,0 AS imp_cnt
    ,0 AS click_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
from basic_shiping_channel_${grass_region_without_quote}
group by 1,2,3,4,5,6,7
;
